<style scoped lang="scss" src="./table-page-indicator.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon.vue";

@Component({
  components: {
    Icon
  }
})
export default class TablePageIndicator extends Vue {
  @Prop({
    type: Number,
    default: 0
  })
  totalPageNumber;

  @Prop({
    type: Number,
    default: 0
  })
  startPage;

  @Prop({
    type: Number,
    default: 10
  })
  displayNumber;

  /**
   * When set true, handlers will only emit event and page info
   * And currentPage will be only changed by startPage
   */
  @Prop({
    type: Boolean,
    default: false
  })
  receiveOnly;

  currentPage = 0;
  currentRange = [0, 0];

  beforeMount() {
    this.currentPage = Math.max(
      Math.min(this.totalPageNumber - 1, this.startPage),
      0
    );

    this.updateRange();
  }

  beforeUpdate() {
    this.currentPage = Math.min(this.totalPageNumber - 1, this.currentPage);

    this.updateRange();
  }

  updateRange() {
    if (this.displayNumber >= this.totalPageNumber) {
      this.currentRange = [0, this.totalPageNumber - 1];
    } else {
      if (this.currentPage + this.displayNumber >= this.totalPageNumber) {
        this.currentRange = [
          this.totalPageNumber - this.displayNumber,
          this.totalPageNumber - 1
        ];
      } else {
        this.currentRange = [
          this.currentPage,
          this.currentPage + this.displayNumber - 1
        ];
      }
    }
  }

  handleClickPrePage() {
    if (this.receiveOnly) {
      if (this.startPage > 0) {
        this.$emit("onChangePage", this.startPage - 1);
        const newPage = this.startPage - 1;

        if (newPage < this.currentRange[0]) {
          this.currentRange[0] = Math.max(
            this.currentRange[0] - this.displayNumber,
            0
          );
          this.currentRange[1] = this.currentRange[0] + this.displayNumber - 1;
        }
      }
    } else {
      if (this.currentPage > 0) {
        this.currentPage--;
        this.$emit("onChangePage", this.currentPage);

        if (this.currentPage < this.currentRange[0]) {
          this.currentRange[0] = Math.max(
            this.currentRange[0] - this.displayNumber,
            0
          );
          this.currentRange[1] = this.currentRange[0] + this.displayNumber - 1;
        }
      }
    }
  }

  handleClickPage(index) {
    if (this.receiveOnly) {
      this.$emit("onChangePage", index - 1 + this.currentRange[0]);
    } else {
      this.currentPage = index - 1 + this.currentRange[0];
      this.$emit("onChangePage", this.currentPage);
    }
  }

  handleClickNextPage() {
    if (this.receiveOnly) {
      if (this.startPage < this.totalPageNumber - 1) {
        this.$emit("onChangePage", this.startPage + 1);

        const newPage = this.startPage + 1;

        if (newPage > this.currentRange[1]) {
          this.currentRange[1] = Math.min(
            this.currentRange[1] + this.displayNumber,
            this.totalPageNumber - 1
          );
          this.currentRange[0] = this.currentRange[1] - this.displayNumber + 1;
        }
      }
    } else {
      if (this.currentPage < this.totalPageNumber - 1) {
        this.currentPage++;
        this.$emit("onChangePage", this.currentPage);
      }

      if (this.currentPage > this.currentRange[1]) {
        this.currentRange[1] = Math.min(
          this.currentRange[1] + this.displayNumber,
          this.totalPageNumber - 1
        );
        this.currentRange[0] = this.currentRange[1] - this.displayNumber + 1;
      }
    }
  }

  handleClickFirstPage() {
    if (this.currentRange[0] > 0) {
      if (!this.receiveOnly) {
        this.currentPage = 0;
      }

      this.$emit("onChangePage", 0);
      this.currentRange = [0, this.displayNumber - 1];
    }
  }

  handleClickLastPage() {
    if (this.currentRange[1] < this.totalPageNumber - 1) {
      if (!this.receiveOnly) {
        this.currentPage = this.totalPageNumber - 1;
      }

      this.$emit("onChangePage", this.totalPageNumber - 1);
      this.currentRange = [
        this.totalPageNumber - this.displayNumber,
        this.totalPageNumber - 1
      ];
    }
  }

  get pageNow() {
    return this.receiveOnly ? this.startPage : this.currentPage;
  }

  get pageNumber() {
    return Math.min(
      this.displayNumber,
      this.totalPageNumber - this.currentRange[0]
    );
  }
}
</script>

<template>
  <div class="TablePageIndicator">
    <div
      :class="[
        'TablePageIndicator__Button',
        currentRange[0] > 0
          ? 'TablePageIndicator--clickable'
          : 'TablePageIndicator--invisible',
        'TablePageIndicator--right_margin'
      ]"
      @click="handleClickFirstPage"
    >
      1...
    </div>
    <div
      :class="[
        'TablePageIndicator__Button',
        pageNow === 0
          ? 'TablePageIndicator--unclickable'
          : 'TablePageIndicator--clickable'
      ]"
      @click="handleClickPrePage"
    >
      ←
    </div>

    <div
      class="TablePageIndicator__Block"
      v-for="index in pageNumber"
      :key="index"
      @click="handleClickPage(index)"
    >
      {{ index + currentRange[0] }}
      <div
        v-if="pageNow === index - 1 + currentRange[0]"
        class="TablePageIndicator__Downline"
      />
    </div>
    <div
      :class="[
        'TablePageIndicator__Button',
        pageNow === totalPageNumber - 1
          ? 'TablePageIndicator--unclickable'
          : 'TablePageIndicator--clickable'
      ]"
      @click="handleClickNextPage"
    >
      →
    </div>
    <div
      :class="[
        'TablePageIndicator__Button',
        currentRange[1] < totalPageNumber - 1
          ? 'TablePageIndicator--clickable'
          : 'TablePageIndicator--invisible',
        'TablePageIndicator--left_margin'
      ]"
      @click="handleClickLastPage"
    >
      {{ `...${totalPageNumber}` }}
    </div>
  </div>
</template>
